questionvariables.text:
correct_answer:rand_selection([
[1, true, "It has male population of various age groups  shown on the positive  side  and the corresponding female population  shown on the negative side of the x-axis.
"],
[2, true, "It has life expectancy of the individuals shown on the pyramid
"],
[3, true, "It can be used to project population growth
"]],1);
incorrect_answers:rand_selection([
[4, false, "It is a triangular solid body having triangular sides meeting in a point at the top"],
[5, false, "It has Age sex distribution of the population presented in a graphical form"],
[6, false, " It has the height of each horizontal bar representing the age group while the length shows the population in each age group"],
[7, false, "It has ages  marked off at the y-axis with ‘0’ as the origin"]], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
